package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.Set;

import org.eclipse.rdf4j.query.algebra.helpers.collectors.VarNameCollector;
import org.junit.jupiter.api.Test;

class ProjectionGraphContextTest {

	@Test
	void cloneOwnsCallerContextAndPreservesItsFrame() {
		Projection projection = projection();
		Projection clone = projection.clone();
		assertEquals(projection, clone);
		assertEquals(projection.hashCode(), clone.hashCode());
		assertNotSame(projection.getProjectionContext(), clone.getProjectionContext());
		assertSame(clone, clone.getProjectionContext().getParentNode());
		clone.getProjectionContext().setGraphContextDepth(2);
		assertEquals(0, projection.getProjectionContext().getGraphContextDepth());
		assertNotEquals(projection, clone);
	}

	@Test
	void callerContextCanBeReplacedWithoutEnteringResultScope() {
		Projection projection = projection();
		Var replacement = Var.of("otherGraph");
		projection.getProjectionContext().replaceWith(replacement);
		assertSame(replacement, projection.getProjectionContext());
		assertSame(projection, replacement.getParentNode());
		assertEquals(Set.of("x"), projection.getBindingNames());
		assertFalse(VarNameCollector.process(projection).contains("otherGraph"));
		assertFalse(VarNameCollector.process(projection).contains("_privateGraph"));
	}

	@Test
	void serializationPreservesCallerAndPrivateParameter() throws Exception {
		Projection projection = projection();
		projection.getProjectionContext().setGraphContextDepth(3);
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(projection);
		}
		Projection restored;
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = (Projection) input.readObject();
		}
		assertEquals(projection, restored);
		assertEquals(3, restored.getProjectionContext().getGraphContextDepth());
		assertEquals("_privateGraph", restored.getInheritedGraphParameter());
		assertEquals(Set.of("x"), restored.getBindingNames());
	}

	@Test
	void sameNamedLocalAndInheritedContextsHaveDistinctMeaning() {
		Projection projection = projection();
		Var inherited = Var.of("g");
		int originalHash = inherited.hashCode();
		inherited.setGraphContextDepth(1);
		assertNotEquals(originalHash, inherited.hashCode());
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("x"), Var.of("p"), Var.of("o"), inherited);
		projection.setArg(pattern);
		assertTrue(projection.isInheritedGraphContext(pattern, inherited));
		Var local = Var.of("g");
		assertNotEquals(local, inherited);
		assertFalse(projection.isInheritedGraphContext(pattern, local));
	}

	private Projection projection() {
		ProjectionElemList elements = new ProjectionElemList();
		elements.addElement(new ProjectionElem("x"));
		Projection projection = new Projection(new SingletonSet(), elements, true);
		projection.setProjectionContext(Var.of("g"));
		projection.setInheritedGraphParameter("_privateGraph");
		return projection;
	}
}
